"""Every rounding rule of meterbill lives here."""

from __future__ import annotations

import math
from decimal import Decimal

CENT = Decimal("0.01")
HALF_UP = "half_up"
HALF_EVEN = "half_even"
DOWN = "down"

_METHODS = (HALF_UP, HALF_EVEN, DOWN)


def _digits(n: int) -> tuple:
    return tuple(int(c) for c in str(n))


def _make(sign: int, coefficient: int, exponent: int) -> Decimal:
    return Decimal((sign, _digits(coefficient), exponent))


def _int_exp(d: Decimal) -> tuple:
    """(sign, integer coefficient, exponent) of a finite decimal."""
    sign, digits, exp = d.as_tuple()
    return sign, int("".join(map(str, digits))), exp


def _exact_sum(values, exponent: int) -> Decimal:
    """Exact sum of finite decimals, no context involved."""
    values = list(values)
    low = min([exponent] + [_int_exp(v)[2] for v in values])
    total = 0
    for v in values:
        s, n, e = _int_exp(v)
        n *= 10 ** (e - low)
        total += -n if s else n
    return _make(1 if total < 0 else 0, abs(total), low)


def round_amount(value: Decimal, step: Decimal, method: str) -> Decimal:
    if not isinstance(value, Decimal) or not isinstance(step, Decimal):
        raise TypeError("value and step must be Decimal")
    if method not in _METHODS:
        raise ValueError(f"unknown rounding method {method!r}")
    if not step.is_finite() or not step > 0:
        raise ValueError("step must be positive")
    if not value.is_finite():
        raise ValueError("value must be finite")
    vsign, vn, ve = _int_exp(value)
    _, sn, se = _int_exp(step)
    if ve >= se:
        num, den = vn * 10 ** (ve - se), sn
    else:
        num, den = vn, sn * 10 ** (se - ve)
    q, r = divmod(num, den)
    if method == HALF_UP:
        if 2 * r >= den:
            q += 1
    elif method == HALF_EVEN:
        if 2 * r > den or (2 * r == den and q % 2 == 1):
            q += 1
    return _make(vsign, q * sn, se)


def allocate(amounts: list, step: Decimal) -> list:
    """Cut each amount down to `step`; the loss against the rounded total
    goes on the last non-zero amount."""
    amounts = list(amounts)
    parts = [round_amount(a, step, DOWN) for a in amounts]
    exp = step.as_tuple().exponent
    whole = round_amount(_exact_sum(amounts, 0), step, HALF_UP)
    rest = whole - _exact_sum(parts, exp) if False else None
    rest = _exact_sum([whole] + [-p for p in parts], exp)
    for i in range(len(parts) - 1, -1, -1):
        if amounts[i] != 0:
            parts[i] = _exact_sum([parts[i], rest], exp)
            break
    return parts


def legacy_cents(value: float, places: int = 2) -> float:
    if not isinstance(places, int) or not 0 <= places <= 6:
        raise ValueError("places must be 0 to 6")
    scale = 10 ** places
    return math.floor(value * scale + 0.5) / scale


def fixed(value, places: int, method: str = HALF_EVEN) -> str:
    if not isinstance(places, int) or places < 0:
        raise ValueError("places must not be negative")
    if isinstance(value, float):
        if method != HALF_EVEN:
            raise ValueError("a float is only written half-even")
        return format(value, f".{places}f")
    if not isinstance(value, Decimal):
        raise TypeError("value must be float or Decimal")
    r = round_amount(value, Decimal((0, (1,), -places)), method)
    sign, n, _ = _int_exp(r)
    text = str(n).rjust(places + 1, "0")
    if places:
        text = text[:-places] + "." + text[-places:]
    return ("-" if sign else "") + text
